import XCTest

/// Captures the screenshots used in the documentation.
///
/// Not a test of anything — it asserts only enough to fail loudly rather than
/// quietly producing a picture of the wrong screen. It lives here because a UI
/// test bundle is the only thing that can drive the app, and because
/// screenshots taken by hand on somebody's phone are stale the moment the UI
/// moves and cannot be regenerated by anyone else.
///
/// **It needs a server with data in it.** The Summary and Insights tabs render
/// what the server computed; against an empty one they are honest and empty.
/// Point it at a throwaway instance holding synthetic data — never at a real
/// health record, because these images get committed. See
/// `docs/SCREENSHOTS.md`.
///
///     xcodebuild test -project HealthExporter.xcodeproj -scheme HealthExporter \
///       -destination 'platform=iOS Simulator,name=iPhone 17 Pro' \
///       -only-testing:HealthExporterUITests/ScreenshotTests
///
/// Skipped unless `SCREENSHOT_SERVER` is set, so a plain `xcodebuild test` on a
/// machine with no demo server does not fail on a fixture it cannot reach.
final class ScreenshotTests: XCTestCase {

    private var app: XCUIApplication!

    override func setUpWithError() throws {
        try XCTSkipIf(
            ProcessInfo.processInfo.environment["SCREENSHOT_SERVER"] == nil,
            "Set SCREENSHOT_SERVER, SCREENSHOT_USER and SCREENSHOT_PASSWORD to capture."
        )
        continueAfterFailure = false
        app = XCUIApplication()
        app.launch()
        XCTAssertTrue(app.wait(for: .runningForeground, timeout: 30))
    }

    func testCaptureEveryTab() throws {
        let environment = ProcessInfo.processInfo.environment
        let server = try XCTUnwrap(environment["SCREENSHOT_SERVER"])
        let user = try XCTUnwrap(environment["SCREENSHOT_USER"])
        let password = try XCTUnwrap(environment["SCREENSHOT_PASSWORD"])

        try signIn(server: server, user: user, password: password)

        // Relaunch before capturing anything.
        //
        // Launch fetches the snapshot, the trends and the model status before
        // this test has signed in, so those first requests go out with whatever
        // stale token was in the Keychain and come back 401. The screens keep
        // that error line — correctly, it was true when it happened — and it is
        // still sitting there after a successful sign-in until something
        // re-fetches. A fresh launch is both a cleaner picture and a more
        // representative one: it is what opening the app normally looks like.
        app.terminate()
        app.launch()
        XCTAssertTrue(app.wait(for: .runningForeground, timeout: 30))

        // Summary last-but-one rather than first: signing in leaves Settings on
        // screen, and every tab wants a moment to fetch before it is worth a
        // picture.
        for tab in ["Summary", "Insights", "Metrics", "Server"] {
            show(tab)
            capture(tab)
        }
        show("Settings")
        capture("Settings")
    }

    // MARK: - Steps

    private func signIn(server: String, user: String, password: String) throws {
        show("Settings")

        let url = app.textFields["https://your-server"].firstMatch
        XCTAssertTrue(url.waitForExistence(timeout: 10), "server URL field")
        url.tap()
        clear(url)
        url.typeText(server)
        // A mangled URL makes `endpoint` nil, which *disables* Sign In — so the
        // tap below would land on nothing and the only symptom would be the
        // thirty-second wait for a "Sign Out" that never arrives.
        XCTAssertEqual(url.value as? String, server, "server URL did not replace cleanly")
        dismissKeyboard()

        // Before anything else, and deliberately after the URL is set.
        //
        // The Simulator keychain is device-wide and survives uninstalling the
        // app, so a token from some earlier session is still there and the app
        // opens already "Signed in" — with no Username field to fill, which is
        // exactly how this test failed the first time. Signing out first makes
        // the run start from a known state.
        //
        // Setting the URL first is the safety property: sign-out POSTs to the
        // *configured* server to revoke, so doing it in this order guarantees
        // that request goes to the throwaway instance and never to whatever the
        // leftover token actually belongs to.
        signOutIfNeeded()

        let username = app.textFields["Username"].firstMatch
        XCTAssertTrue(scrollTo(username), "username field")
        username.tap()
        username.typeText(user)
        dismissKeyboard()

        let secure = app.secureTextFields["Password"].firstMatch
        XCTAssertTrue(scrollTo(secure), "password field")
        secure.tap()
        secure.typeText(password)
        dismissKeyboard()

        let button = app.buttons["Sign In"].firstMatch
        XCTAssertTrue(scrollTo(button), "Sign In button")
        XCTAssertTrue(button.isEnabled, "Sign In is disabled — the URL or credentials did not take")
        button.tap()

        // The token has to land before any other tab has anything to show.
        let signedIn = app.buttons["Sign Out"].firstMatch
        XCTAssertTrue(signedIn.waitForExistence(timeout: 30), "sign-in did not complete")

        enableUploading()
    }

    /// Clears any credential left over from a previous session.
    private func signOutIfNeeded() {
        let signOut = app.buttons["Sign Out"].firstMatch
        guard scrollTo(signOut, attempts: 8) else { return }
        signOut.tap()
        // The confirmation, where the button carries a destructive role.
        let confirm = app.alerts.buttons["Sign Out"].firstMatch
        if confirm.waitForExistence(timeout: 3) { confirm.tap() }
        XCTAssertTrue(
            app.textFields["Username"].firstMatch.waitForExistence(timeout: 15),
            "sign-out did not return the form"
        )
    }

    /// Signing out switches uploading off — a credential-less upload would only
    /// park every batch on a 401 — and signing back in does not switch it on
    /// again. The Server tab warns about a queue with uploading disabled, so
    /// leaving it off would put a caveat in the screenshot about the test's own
    /// housekeeping.
    private func enableUploading() {
        let toggle = app.switches["Upload automatically"].firstMatch
        guard scrollTo(toggle, attempts: 10) else { return }
        if (toggle.value as? String) == "0" { toggle.tap() }
    }

    private func show(_ tab: String) {
        app.tabBars.buttons[tab].tap()
        // The measured figures arrive in one query and the generated text does
        // not; this waits for the former and deliberately not the latter.
        Thread.sleep(forTimeInterval: 3)
    }

    private func capture(_ name: String) {
        let shot = XCTAttachment(screenshot: XCUIScreen.main.screenshot())
        shot.name = name
        shot.lifetime = .keepAlways
        add(shot)
    }

    /// Puts the keyboard away.
    ///
    /// Not cosmetic: a field below the fold is not `isHittable` while the
    /// keyboard is over it, so `scrollTo` scrolls to the bottom and still
    /// reports failure. There is no Done button on these fields, so this taps
    /// the navigation title — inert, and always on screen.
    private func dismissKeyboard() {
        guard app.keyboards.element.exists else { return }
        app.staticTexts["Settings"].firstMatch.tap()
        _ = app.keyboards.element.waitForNonExistence(timeout: 3)
    }

    /// Empties a text field.
    ///
    /// XCUITest has no "clear" — and the select-all-then-replace trick depends
    /// on an edit menu that does not always come up under automation. Deleting
    /// character by character is slower and always works. An empty field
    /// reports its placeholder as its value, which is the one case that must
    /// not be deleted.
    private func clear(_ field: XCUIElement) {
        guard let current = field.value as? String,
              !current.isEmpty,
              current != field.placeholderValue else { return }
        field.typeText(String(repeating: XCUIKeyboardKey.delete.rawValue, count: current.count))
    }

    /// Scrolls until `element` is on screen, or gives up.
    ///
    /// Swipes whichever scrollable container the OS actually built. A SwiftUI
    /// `List` was a `UITableView` for years and is a collection view on iOS 26,
    /// so asking for `app.tables` by name finds nothing and the swipe throws
    /// rather than returning false.
    @discardableResult
    private func scrollTo(_ element: XCUIElement, attempts: Int = 12) -> Bool {
        for _ in 0..<attempts {
            if element.exists && element.isHittable { return true }
            // Hittable, not merely existing: the chat history drawer is a
            // collection view parked off the left edge, and it matches first.
            // Swiping it throws — "visible frame is empty" — rather than
            // scrolling the list actually on screen.
            let candidates = app.collectionViews.allElementsBoundByIndex
                + app.tables.allElementsBoundByIndex
                + app.scrollViews.allElementsBoundByIndex
            let scroller: XCUIElement = candidates.first { $0.exists && $0.isHittable } ?? app
            scroller.swipeUp()
        }
        return element.exists && element.isHittable
    }
}
